windowclass.script:
function onInit()
	header.setValue(Interface.getString("ccwiz_head_abilities"));
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_abilities") .. "\r\r" .. Interface.getString("ccwiz_steps_abilities"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_abilities");
	if sub_panel.subwindow then sub_panel.subwindow.onPageShow(); end
end

local STATS = { "strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma" };
function onInit()
	method.add("3d6", Interface.getString("ccwiz_method_3d6"));
	method.add("4d6", Interface.getString("ccwiz_method_4d6"));
	method.add("3d6order", Interface.getString("ccwiz_method_3d6order"));
	onPageShow();
end
function onPageShow()
	local S = CCWizard.getState();
	method.setValue(CCWizard.getMethod());
	method.setReadOnly(CCWizard.getForcedMethod() ~= nil);
	hint.setValue(Interface.getString(CCWizard.getMethod() == "3d6order" and "ccwiz_hint_order" or "ccwiz_hint_swap"));
	for _, s in ipairs(STATS) do
		local n = S.scores[s];
		local nFinal = CCWizard.getFinalScore(s);
		self["score_" .. s].setValue(n or 0);
		local nRace = CCWizard.getRaceMod(s);
		self["race_" .. s].setValue(nRace ~= 0 and string.format("%+d", nRace) or "");
		self["total_" .. s].setValue(nFinal and tostring(nFinal) or "");
		self["mod_" .. s].setValue(nFinal and string.format("%+d", CCWizard.getModifier(nFinal)) or "");
	end
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_race") .. "\r\r" .. Interface.getString("ccwiz_steps_race"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_race");
	local nodeSel = CCWizard.getRaceNode();
	local bPick = nodeSel == nil;
	sub_filter.setVisible(bPick);
	list.setVisible(bPick);
	sub_chosen.setVisible(not bPick);
	change.setVisible(not bPick);
	traits_header.setVisible(not bPick);
	cards.setVisible(not bPick);
	if bPick then
		header.setValue(Interface.getString("ccwiz_header_races"));
		sub_filter.subwindow.setKind("race", "Race");
		list.closeAll();
		for _, node in ipairs(CCWizard.getPickList("Race", "race")) do
			list.createWindow().setData(node, "race");
		end
		return;
	end
	header.setValue(DB.getValue(nodeSel, "name", ""):upper());
	sub_chosen.subwindow.setRace(nodeSel);
	cards.closeAll();
	for _, v in pairs(DB.getChildren(nodeSel, "abilities")) do
		cards.createWindow().setData(DB.getValue(v, "name", ""), CCWizard.plainText(DB.getValue(v, "text", "")), false);
	end
	cards.applySort();
end

function setRace(node)
	name.setValue(DB.getValue(node, "name", ""));
	local tLines = {};
	table.insert(tLines, Interface.getString("ccwiz_label_mods") .. ": " .. CCWizard.describeMods(node));
	local sMove = DB.getValue(node, "speed", "");
	if sMove ~= "" then
		table.insert(tLines, Interface.getString("ccwiz_label_move") .. ": " .. sMove);
	end
	table.insert(tLines, string.format("Extra primes to choose: %d", DB.getValue(node, "primechoice", 0)));
	local tLang = CCWizard.getRaceLanguages(node);
	if #tLang > 0 then
		table.insert(tLines, "Languages: " .. table.concat(tLang, ", "));
	end
	table.insert(tLines, "Source: " .. CCWizard.getSourceName(node));
	info.setValue(table.concat(tLines, "\n"));
	CCWizard.setPortrait(portrait, "race", DB.getValue(node, "name", ""));
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_class") .. "\r\r" .. Interface.getString("ccwiz_steps_class"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_class");
	local nodeSel = CCWizard.getClassNode();
	local bPick = nodeSel == nil;
	sub_filter.setVisible(bPick);
	list.setVisible(bPick);
	sub_chosen.setVisible(not bPick);
	change.setVisible(not bPick);
	abilities_header.setVisible(not bPick);
	cards.setVisible(not bPick);
	combine_header.setVisible(not bPick);
	sub_combine.setVisible(not bPick);
	combos.setVisible(not bPick);
	picks.setVisible(not bPick);
	if bPick then
		header.setValue(Interface.getString("ccwiz_header_classes"));
		-- Race first: the race decides which classes can be taken.
		local bRace = CCWizard.getRaceNode() ~= nil;
		sub_filter.setVisible(bRace);
		list.setVisible(bRace);
		needrace.setVisible(not bRace);
		if bRace then sub_filter.subwindow.setKind("class", "Class"); end
		list.closeAll();
		if not bRace then return; end
		for _, node in ipairs(CCWizard.getPickList("Class", "class")) do
			list.createWindow().setData(node, "class");
		end
		return;
	end
	needrace.setVisible(false);
	header.setValue(DB.getValue(nodeSel, "name", ""):upper());
	sub_chosen.subwindow.setClass(nodeSel);
	refreshCombine();
	cards.closeAll();
	local nLevel = CCWizard.getStartLevel();
	for _, v in pairs(DB.getChildren(nodeSel, "abilities")) do
		local n = tonumber(DB.getValue(v, "level", 1)) or 1;
		if n <= nLevel then
			local w = cards.createWindow();
			w.setData(string.format("(Level %02d)  %s", n, DB.getValue(v, "name", "")), CCWizard.plainText(DB.getValue(v, "text", "")), false);
		end
	end
	cards.applySort();
end
-- Combining classes (Adventurer's Backpack): chosen ones as cards, and
-- the choice list of the option being added.
function refreshCombine()
	if sub_combine.subwindow then sub_combine.subwindow.update(); end
	combos.closeAll();
	for _, t in ipairs(CCWizard.describeCombos()) do
		combos.createWindow().setData(t);
	end
	picks.closeAll();
	local sMode = CCWizard.getPicker();
	if sMode then
		for _, t in ipairs(CCWizard.getComboChoices(sMode)) do
			picks.createWindow().setData(t, sMode);
		end
	end
end

function update()
	local bOk, sWhy = CCWizard.canCombine();
	local C = CCWizard.getCombo();
	local sPicker = CCWizard.getPicker();
	note.setValue(bOk and Interface.getString("ccwiz_combine_note") or sWhy);
	local bOne = C.class2 ~= nil or C.support ~= nil;
	add_multi.setVisible(bOk and not bOne);
	add_support.setVisible(bOk and not bOne);
	add_plus.setVisible(bOk);
	add_multi.setText(sPicker == "multi" and "Cancel" or Interface.getString("ccwiz_btn_addmulti"));
	add_support.setText(sPicker == "enhanced" and "Cancel" or Interface.getString("ccwiz_btn_addsupport"));
	add_plus.setText(sPicker == "plus" and "Cancel" or Interface.getString("ccwiz_btn_addplus"));
end

local _sMode, _sPath = "", "";
function setData(t)
	_sMode, _sPath = t.mode, t.path;
	title.setValue(t.title);
	text.setValue(t.text);
end
function onRemove()
	CCWizard.removeCombo(_sMode, _sPath);
end

local _t, _sMode = nil, "";
function setData(t, sMode)
	_t, _sMode = t, sMode;
	name.setValue(t.name);
	code.setValue(t.code ~= "" and ("[" .. t.code .. "]") or "");
	rule.setValue(t.rule);
	source.setValue(t.source or "");
	add.setVisible(t.allowed);
end
function onAdd()
	CCWizard.chooseCombo(_sMode, _t.path, _t.key);
end
function onOpen()
	CCWizard.openRecord(_t.path);
end

function setClass(node)
	local nLevel = CCWizard.getStartLevel();
	name.setValue(DB.getValue(node, "name", ""));
	level.setValue(nLevel);
	local tLines = {};
	-- A level past the printed table gets one line (the Castle Keeper's HP and
	-- BtH, below); a level the package lacks says so here.
	if not CCWizard.hasSupportedLevel() and not CCWizard.requiresManualProgression() then
		table.insert(tLines, CCWizard.getUnsupportedLevelMessage());
	end
	local sPrime = CCWizard.getClassPrime();
	table.insert(tLines, Interface.getString("ccwiz_label_prime") .. ": " .. (sPrime and StringManager.capitalize(sPrime) or "-"));
	table.insert(tLines, Interface.getString("ccwiz_label_hitdie") .. ": " .. DB.getValue(node, "hitdie", "-"));
	local nodeRow = CCWizard.getExactLevelRow(node, nLevel);
	if nodeRow and not CCWizard.requiresManualProgression() then
		table.insert(tLines, string.format("%s: %+d", Interface.getString("ccwiz_label_bth"), DB.getValue(nodeRow, "bth", 0)));
		table.insert(tLines, "Hit dice at this level: " .. DB.getValue(nodeRow, "hd", ""));
	elseif CCWizard.requiresManualProgression() then
		table.insert(tLines, Interface.getString("ccwiz_label_manualrequired"));
	end
	local sGold = DB.getValue(node, "startgold", "");
	if sGold ~= "" then
		table.insert(tLines, Interface.getString("ccwiz_label_gold") .. ": " .. sGold:gsub("x", " x ") .. " gp");
	end
	table.insert(tLines, "Source: " .. CCWizard.getSourceName(node));
	info.setValue(table.concat(tLines, "\n"));
	CCWizard.setPortrait(portrait, "class", DB.getValue(node, "name", ""));
	-- A class with no portrait (another book's) uses the whole width.
	local nX = portrait.isVisible() and 220 or 10;
	name.setStaticBounds(nX, 10, -200, 30);
	info.setStaticBounds(nX, 48, -10, 200);
end
function changeLevel(nDelta)
	CCWizard.setStartLevel(CCWizard.getStartLevel() + nDelta);
	CCWizard.refreshAll();
end

function onInit()
	header.setValue(Interface.getString("ccwiz_head_primes"));
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_primes") .. "\r\r" .. Interface.getString("ccwiz_steps_primes"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_primes");
	if sub_panel.subwindow then sub_panel.subwindow.onPageShow(); end
end

local STATS = { "strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma" };
local _bUpdating = false;
function onInit()
	onPageShow();
end
function isUpdating()
	return _bUpdating;
end
function onPageShow()
	if _bUpdating then
		return;
	end
	_bUpdating = true;
	local S = CCWizard.getState();
	for _, s in ipairs(STATS) do
		local sForced = CCWizard.isForcedPrime(s);
		local c = self["prime_" .. s];
		c.setValue((sForced or S.primes[s]) and 1 or 0);
		c.setReadOnly(sForced ~= nil);
		local nScore = CCWizard.getFinalScore(s);
		self["note_" .. s].setValue((nScore and tostring(nScore) or "-") .. (sForced and ("   (" .. sForced .. ")") or ""));
	end
	local nChosen, nAllowed = CCWizard.getPrimeCounts();
	count.setValue(string.format(Interface.getString("ccwiz_primes_count"), nChosen, nAllowed));
	_bUpdating = false;
end

function onInit()
	header.setValue(Interface.getString("ccwiz_head_hp"));
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_hp") .. "\r\r" .. Interface.getString("ccwiz_steps_hp"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_hp");
	if sub_panel.subwindow then sub_panel.subwindow.onPageShow(); end
end

function onInit()
	onPageShow();
end
function onPageShow()
	local S = CCWizard.getState();
	local tLines = {};
	local nCon = CCWizard.getConMod();
	local bManual = CCWizard.requiresManualProgression();
	roll.setVisible(not bManual);
	manual_note.setVisible(bManual);
	manual_hp_label.setVisible(bManual);
	entry_manualhp.setVisible(bManual);
	manual_bth_label.setVisible(bManual);
	entry_manualbth.setVisible(bManual);
	-- Manual levels: the note, the two boxes, then the total under them (the
	-- plan only repeats the note, so it is hidden).
	plan.setVisible(not bManual);
	if bManual then total.setStaticBounds(60,88,400,24); else total.setStaticBounds(270,12,400,24); end
	if bManual then
		manual_note.setValue(CCWizard.getUnsupportedLevelMessage());
		entry_manualhp.setValue(S.manualhp or "");
		entry_manualbth.setValue(S.manualbth or "");
	end
	for _, r in ipairs(CCWizard.getHPPlan()) do
		local sDice = (#r.dice > 0) and ("1" .. r.dice[1] .. (#r.dice > 1 and (" x" .. #r.dice) or "")) or "";
		if #r.dice > 0 and nCon ~= 0 then
			sDice = sDice .. string.format(" %+d Con", nCon);
		end
		if r.flat > 0 then
			sDice = sDice .. (sDice ~= "" and " " or "") .. string.format("+%d", r.flat);
		end
		table.insert(tLines, string.format("%s:   %s   %s", string.format(Interface.getString("ccwiz_hp_level"), r.level),
			sDice, S.hp[r.level] and ("= " .. S.hp[r.level]) or ""));
	end
	if #tLines == 0 then
		table.insert(tLines, bManual and Interface.getString("ccwiz_label_manualrequired") or Interface.getString("ccwiz_msg_noclass"));
	end
	if S.hpnotice then table.insert(tLines, 1, S.hpnotice); end
	plan.setValue(table.concat(tLines, "\n"));
	total.setValue(string.format(Interface.getString("ccwiz_hp_total"), CCWizard.getSelectedHPTotal()));
end

local _node = nil;
function setData(node)
	_node = node;
	name.setValue(DB.getValue(node, "name", ""));
	cost.setValue(DB.getValue(node, "cost", ""));
end
function onBuy()
	CCWizard.buy(_node);
end
function onOpen()
	Interface.openWindow("item", DB.getPath(_node));
end

local _sPath = "";
function setData(t)
	_sPath = t.path;
	name.setValue(t.name .. (t.count > 1 and (" x" .. t.count) or ""));
	cost.setValue(CCWizard.formatCopper(t.cost * t.count));
end
function onReturn()
	CCWizard.unbuy(_sPath);
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_equipment") .. "\r\r" .. Interface.getString("ccwiz_steps_equipment"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_equipment");
	if sub_coin.subwindow then sub_coin.subwindow.onPageShow(); end
	if sub_shop.subwindow then sub_shop.subwindow.refreshShop(); end
	local S = CCWizard.getState();
	cart.closeAll();
	for _, t in ipairs(S.cart) do
		cart.createWindow().setData(t);
	end
	cart_empty.setVisible(#S.cart == 0);
end

function onInit()
	onPageShow();
end
function onPageShow()
	local S = CCWizard.getState();
	if S.gold then
		purse.setValue(S.gold .. " gp");
		spent.setValue(CCWizard.formatCopper(CCWizard.getSpent()));
		left.setValue(CCWizard.formatCopper(CCWizard.getLeft()));
	else
		purse.setValue("-");
		spent.setValue("-");
		left.setValue("-");
	end
end

local _sCategory = "all";
function onInit()
	for _, t in ipairs({ { "all", "ccwiz_cat_all" }, { "weapon", "ccwiz_cat_weapon" }, { "armor", "ccwiz_cat_armor" },
			{ "gear", "ccwiz_cat_gear" }, { "clothing", "ccwiz_cat_clothing" }, { "provisions", "ccwiz_cat_provisions" },
			{ "transport", "ccwiz_cat_transport" } }) do
		category.add(t[1], Interface.getString(t[2]));
	end
	category.setValue("all");
	refreshShop();
end
function setCategory(s)
	_sCategory = s or "all";
	refreshShop();
end
function refreshShop()
	shop.closeAll();
	local tItems = CCWizard.getShopItems(_sCategory, search.getValue());
	for _, node in ipairs(tItems) do
		shop.createWindow().setData(node);
	end
	if not CCWizard.getClassNode() then
		shopnote.setValue(Interface.getString("ccwiz_shop_classfirst"));
	elseif not CCWizard.getState().gold then
		shopnote.setValue(Interface.getString("ccwiz_shop_rollfirst"));
	elseif #tItems == 0 then
		shopnote.setValue(Interface.getString("ccwiz_shop_nothing"));
	else
		shopnote.setValue("");
	end
	shopnote.setVisible(shopnote.getValue() ~= "");
end

local _sPath = "";
local _bSetting = false;
function setData(t, bOn)
	_sPath = DB.getPath(t.node);
	level.setValue(tostring(t.level));
	name.setValue(DB.getValue(t.node, "name", ""));
	_bSetting = true;
	pick.setValue(bOn and 1 or 0);
	_bSetting = false;
end
function onPick(bOn)
	if _bSetting then
		return;
	end
	if CCWizard.toggleSpell(_sPath, bOn) == false then
		_bSetting = true;
		pick.setValue(0);
		_bSetting = false;
	end
	windowlist.window.updateCount();
end
function onOpen()
	Interface.openWindow("spell", DB.getValue(_sPath .. ".officialpath", _sPath));
end

function onInit()
	header.setValue(Interface.getString("ccwiz_head_spells"));
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_spells") .. "\r\r" .. Interface.getString("ccwiz_steps_spells"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_spells");
	if sub_panel.subwindow then sub_panel.subwindow.onPageShow(); end
end

local _nLevel = nil;
function onInit()
	onPageShow();
end
function updateCount()
	local sPicks = CCWizard.describeSpellPicks();
	chosen.setValue(string.format(Interface.getString("ccwiz_spells_chosen"), sPicks));
end
function setLevel(s)
	_nLevel = tonumber(s);
	refreshList();
end
function buildLevels()
	levelfilter.clear();
	levelfilter.add("all", Interface.getString("ccwiz_spells_alllevels"));
	for i = 0, CCWizard.getMaxSpellLevel() do
		levelfilter.add(tostring(i), i == 0 and Interface.getString("ccwiz_spells_level0") or string.format(Interface.getString("ccwiz_spells_leveln"), i));
	end
	if not _nLevel or _nLevel > CCWizard.getMaxSpellLevel() then
		_nLevel = nil;
	end
	levelfilter.setValue(_nLevel and tostring(_nLevel) or "all");
end
function refreshList()
	local tPicks = CCWizard.getSpellPicks();
	list.closeAll();
	for _, t in ipairs(CCWizard.getSpellChoices(search.getValue(), _nLevel)) do
		list.createWindow().setData(t, tPicks[DB.getPath(t.node)] ~= nil);
	end
	updateCount();
end
-- Two spell lists (combined classes): a button for each, as the
-- 5e wizard's Features / Spells toggles.
function updateSets()
	local bTwo = CCWizard.hasSecondSpells();
	set_main.setVisible(bTwo);
	set_second.setVisible(bTwo);
	if bTwo then
		local sSet = CCWizard.getSpellSet();
		set_main.setText(CCWizard.getMainSpellClass() ~= "" and CCWizard.getMainSpellClass() or CCWizard.getClassName());
		set_second.setText(CCWizard.getSecondSpellClass());
		set_main.setFrame(sSet == "main" and "buttondown" or "buttonup", 5, 5, 5, 5);
		set_second.setFrame(sSet == "second" and "buttondown" or "buttonup", 5, 5, 5, 5);
	end
end
function onPageShow()
	updateSets();
	if CCWizard.getSpellClass() == "" then
		perday.setValue(Interface.getString("ccwiz_spells_none"));
		list.closeAll();
		chosen.setValue("");
		return;
	end
	local tDay = CCWizard.getSpellsPerDay();
	local tParts = {};
	for i = 0, 9 do
		if tDay[i] and tDay[i] > 0 then
			table.insert(tParts, string.format("%s: %d", i == 0 and "0-level" or ("level " .. i), tDay[i]));
		end
	end
	perday.setValue(string.format(Interface.getString("ccwiz_spells_perday"), CCWizard.getStartLevel(), table.concat(tParts, ", ")));
	buildLevels();
	refreshList();
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("ccwiz_lore_finish") .. "\r\r" .. Interface.getString("ccwiz_steps_finish"));
	onPageShow();
end
function onPageShow()
	CCWizard.applyWallpaper(wallpaper, "ccwiz_art_finish");
	updateSummary();
end
function updateSummary()
	local tWarnings = CCWizard.getAllWarnings();
	warnings.closeAll();
	for _, s in ipairs(tWarnings) do
		warnings.createWindow().text.setValue(s);
	end
	nowarnings.setVisible(#tWarnings == 0);
	if sub_details.subwindow and sub_details.subwindow.refreshAlignments then sub_details.subwindow.refreshAlignments(); end
	if sub_save.subwindow then sub_save.subwindow.update(); end
	if sub_summary.subwindow then sub_summary.subwindow.update(); end
end

function onInit()
	refreshAlignments();
end
-- Only the alignments the chosen classes allow (the C&C class entries).
function refreshAlignments()
	local S = CCWizard.getState();
	local tAllowed, sRules = CCWizard.getAllowedAlignments();
	local sSig = table.concat(tAllowed, "|");
	if sSig ~= _sAlignSig then
		_sAlignSig = sSig;
		alignment.clear();
		for _, s in ipairs(tAllowed) do
			alignment.add(s, s);
		end
	end
	if not CCWizard.isAlignmentValid() then
		S.alignment = "";
	end
	alignment.setValue(S.alignment or "");
	alignment.setTooltipText(sRules ~= "" and string.format(Interface.getString("ccwiz_label_alignrule"), sRules) or "");
end
function updateSummary()
	local wPage = parentcontrol and parentcontrol.window;
	if wPage and wPage.updateSummary then
		wPage.updateSummary();
	end
end

function update()
	-- Always available: an unfinished character is saved with
	-- its open choices in the notes (CCWizard.createCharacter).
	create.setEnabled(true);
end

local STATS = { "strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma" };
function update()
	local S = CCWizard.getState();
	local nodeRace, nodeClass = CCWizard.getRaceNode(), CCWizard.getClassNode();
	for _, s in ipairs(STATS) do
		local n = CCWizard.getFinalScore(s);
		local bPrime = CCWizard.isForcedPrime(s) or S.primes[s];
		self["total_" .. s].setValue(n and tostring(n) or "");
		self["mod_" .. s].setValue(n and string.format("%+d", CCWizard.getModifier(n)) or "");
		self["prime_" .. s].setVisible(bPrime and true or false);
	end
	local tLines = {};
	table.insert(tLines, string.format("Name: %s      Alignment: %s", StringManager.trim(S.name or "") ~= "" and S.name or "-", (S.alignment or "") ~= "" and S.alignment or "-"));
	table.insert(tLines, string.format("Race: %s      Class: %s %d", nodeRace and DB.getValue(nodeRace, "name", "") or "-",
		nodeClass and DB.getValue(nodeClass, "name", "") or "-", CCWizard.getStartLevel()));
	table.insert(tLines, string.format("Hit points: %d      Coin left: %s      Items: %d      Spells: %d",
		CCWizard.getSelectedHPTotal(), S.gold and CCWizard.formatCopper(CCWizard.getLeft()) or "-", #S.cart, CCWizard.countSpells()));
	summary.setValue(table.concat(tLines, "\n"));
end
